def make_default_action_roles(*, ROLE_ACTION_PERMISSION_GROUPS):
    return {(item['key'], action): set(roles) for group in ROLE_ACTION_PERMISSION_GROUPS for item in group['items'] for action, roles in item['actions'].items()}

def apply_manager_finance_inheritance(DEFAULT_ACTION_ROLES, MANAGER_FINANCE_INHERITANCE_EXCEPTIONS, *, _assign_iteration):
    for _permission_key, _roles in DEFAULT_ACTION_ROLES.items():
        _assign_iteration(_permission_key, _roles)
        if 'finance' in _roles and _permission_key not in MANAGER_FINANCE_INHERITANCE_EXCEPTIONS:
            _roles.add('manager')
